describe('Login Form Validation - Empty Fields', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should prevent form submission with empty username or password fields', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Attempt to submit with empty username
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="username-input"]').type('');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    // Wait for the API call to complete
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
      expect(interception.response.body.error).to.include('Username is required');
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Username is required');

    // Verify form is still visible
    cy.get('[data-testid="login-form"]').should('be.visible');
  });

  it('should prevent form submission with empty password field', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Attempt to submit with empty password
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="username-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('');
    cy.get('[data-testid="login-button"]').click();

    // Wait for the API call to complete
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
      expect(interception.response.body.error).to.include('Password is required');
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Password is required');

    // Verify form is still visible
    cy.get('[data-testid="login-form"]').should('be.visible');
  });

  it('should prevent form submission with both fields empty', () => {
    // Intercept the login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Attempt to submit with both fields empty
    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="username-input"]').type('');
    cy.get('[data-testid="password-input"]').type('');
    cy.get('[data-testid="login-button"]').click();

    // Wait for the API call to complete
    cy.wait('@loginRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
      expect(interception.response.body.error).to.include('Username and password are required');
    });

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Username and password are required');

    // Verify form is still visible
    cy.get('[data-testid="login-form"]').should('be.visible');
  });
});
